Definition p1_foreign (Arc A : AS) (q : word) : Prop :=
  (exists n, live Arc q = Some n) \/ (exists n, live A q = Some n /\ (n mod 4 <> 0)%Z).

Lemma p1_foreign_ne : forall C Arc A m pixd w h cd data cv (q : word), pix1_at C Arc A m pixd w h cd data cv -> p1_foreign Arc A q ->
  q <> Z_to_bv 64 pixd /\ q <> Z_to_bv 64 data /\ (cd <> 0%Z -> q <> Z_to_bv 64 cd /\ q <> Z_to_bv 64 (c_arr cv)).
