(* [comment removed for export] *)
Definition p1_blks_ok (Arc A : AS) (E : env) (blks : list (expr * Z * Z)) : Prop :=
  Forall (fun b => match b with (pb, q, n) => edenot E pb = Z_to_bv 64 q /\ (0 <= q < 2 ^ 64)%Z /\ live A (Z_to_bv 64 q) = Some n /\ p1_foreign Arc A (Z_to_bv 64 q) end) blks.

Lemma p1_sess : forall C Arc A m md E log (rb : expr) (s F : Z) (blks : list (expr * Z * Z)) pixd w h cd data cv,
  Cok C -> W C A m md -> (c_top C - LSTK <= s - F)%Z -> log_flat E log ->
  ex_in_regions ((rb, (- F)%Z, 0%Z) :: map exW_blk_region blks) log = true -> edenot E rb = Z_to_bv 64 s -> (0 <= s < 2 ^ 64)%Z ->
  p1_blks_ok Arc A E blks -> pix1_at C Arc A m pixd w h cd data cv -> pix1_at C Arc A (mem_denot E m log) pixd w h cd data cv.
Proof.
