(* [comment removed for export] *)
Lemma p1_of_pixt_aux : forall C A A' m' pixd w h cd data cv, pixt_new C A A' m' pixd w h 1 cd data cv ->
  exists cv', pix1_at C A A' m' pixd w h cd data cv' /\ (cd <> 0%Z -> c_d cv' = c_d cv /\ c_nalloc cv' = c_nalloc cv /\ c_n cv' = c_n cv) /\
    ((cd = 0%Z /\ forall q, q <> Z_to_bv 64 pixd -> q <> Z_to_bv 64 data -> live A' q = live A q)
