Lemma p1_of_pixt' : forall C A A' m' pixd w h cd data cv, pixt_new C A A' m' pixd w h 1 cd data cv ->
  exists cv', pix1_at C A A' m' pixd w h cd data cv' /\
    ((cd = 0%Z /\ forall q, q <> Z_to_bv 64 pixd -> q <> Z_to_bv 64 data -> live A' q = live A q)
