Lemma p1_rest_new : forall Ar A A' pixd data cd cv' (bl : list word), (forall q, ~ In q bl -> live A q = live Ar q) ->
  ((cd = 0%Z /\ forall q, q <> Z_to_bv 64 pixd -> q <> Z_to_bv 64 data -> live A' q = live A q)
   \/ (cd <> 0%Z /\ forall q, q <> Z_to_bv 64 pixd -> q <> Z_to_bv 64 data -> q <> Z_to_bv 64 cd -> q <> Z_to_bv 64 (c_arr cv') -> live A' q = live A q)) ->
